#include <queue>
#include <iostream>

int main() {
    std::queue<int> q;

    // Preferred and potentially faster
    while (!q.empty()) { 
        q.pop();
    }

    // Semantically equivalent, but less preferred
    if (q.size() == 0) {
        std::cout << "Queue is confirmed empty.\n";
    }
}
